'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { BarChart, Activity, Shield, Trophy } from 'lucide-react'

interface TeamStat {
    team_number: number
    avg_score: number
    climb_rate: number
    avg_defense: number
    match_count: number
}

export default function AnalyticsDashboard() {
    const [stats, setStats] = useState<TeamStat[]>([])
    const [loading, setLoading] = useState(true)

    const supabase = createClient()

    useEffect(() => {
        async function fetchStats() {
            // In a real app, use a database view or RPC for performance.
            // Here we will fetch raw data and aggregate client-side for simplicity/speed of dev.
            const { data, error } = await supabase
                .from('match_scouting')
                .select('*')

            if (error) {
                console.error('Error fetching stats:', error)
                setLoading(false)
                return
            }

            if (!data) return

            // Aggregate data
            const teamMap = new Map<number, {
                totalScore: number,
                climbs: number,
                totalDefense: number,
                matches: number
            }>()

            data.forEach((match: any) => {
                if (match.is_practice_match) return // specific requirement: ignore practice matches

                const current = teamMap.get(match.team_number) || { totalScore: 0, climbs: 0, totalDefense: 0, matches: 0 }

                current.totalScore += (match.auto_fuel_scored || 0) + (match.teleop_fuel_scored || 0)
                current.climbs += match.teleop_descended_from_auto || match.auto_climb ? 1 : 0 // Simplified climb logic
                current.totalDefense += match.defense_rating || 0
                current.matches += 1

                teamMap.set(match.team_number, current)
            })

            const computedStats: TeamStat[] = Array.from(teamMap.entries()).map(([team, val]) => ({
                team_number: team,
                avg_score: val.totalScore / val.matches,
                climb_rate: (val.climbs / val.matches) * 100,
                avg_defense: val.totalDefense / val.matches,
                match_count: val.matches
            })).sort((a, b) => b.avg_score - a.avg_score) // Default sort by score

            setStats(computedStats)
            setLoading(false)
        }

        fetchStats()
    }, [])

    if (loading) return <div className="p-8">Loading Analytics...</div>

    return (
        <div className="space-y-6">
            <h2 className="text-3xl font-bold tracking-tight">Team Analytics</h2>

            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Top Scorer</CardTitle>
                        <Trophy className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{stats.length > 0 ? `Team ${stats[0].team_number}` : 'N/A'}</div>
                        <p className="text-xs text-muted-foreground">
                            {stats.length > 0 ? `${stats[0].avg_score.toFixed(1)} pts/match` : 'No data'}
                        </p>
                    </CardContent>
                </Card>
                {/* More summary cards could go here */}
            </div>

            <div className="rounded-md border">
                <div className="relative w-full overflow-auto">
                    <table className="w-full caption-bottom text-sm text-left">
                        <thead className="[&_tr]:border-b">
                            <tr className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Rank</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Team</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Avg Score</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Climb %</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Defense Rating</th>
                                <th className="h-12 px-4 align-middle font-medium text-muted-foreground">Matches</th>
                            </tr>
                        </thead>
                        <tbody className="[&_tr:last-child]:border-0">
                            {stats.map((team, index) => (
                                <tr key={team.team_number} className="border-b transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted">
                                    <td className="p-4 align-middle font-bold">#{index + 1}</td>
                                    <td className="p-4 align-middle text-primary font-bold">{team.team_number}</td>
                                    <td className="p-4 align-middle">{team.avg_score.toFixed(1)}</td>
                                    <td className="p-4 align-middle">{team.climb_rate.toFixed(0)}%</td>
                                    <td className="p-4 align-middle">{team.avg_defense.toFixed(1)}</td>
                                    <td className="p-4 align-middle">{team.match_count}</td>
                                </tr>
                            ))}
                            {stats.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="p-4 text-center text-muted-foreground">No match data available.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    )
}
